package org.sleepwell.app;

import android.app.*;
import android.content.*;
import android.os.*;
import android.view.*;
import android.widget.*;
import java.time.*;
import java.time.format.DateTimeFormatter;
import java.util.*;
import java.util.concurrent.*;

/** Board 05 sleep goal and schedule editor. Drafts do not schedule or persist. */
public final class PlanActivity extends Activity {
    private SleepPlan draft;
    private SortedMap<LocalDate,RecordTrends.Day> days=new TreeMap<>();
    private List<RecordEntry> records=List.of();
    private final ExecutorService reader=Executors.newSingleThreadExecutor();
    private final Handler handler=new Handler(Looper.getMainLooper());
    private String failure="",saveToken,reminderFailure="",saveFailure="";private boolean resumed,reminderOnly;
    private Button save;private boolean historyLoaded;private Dialog pickerDialog;private Bundle restoredPicker;
    @Override public void onCreate(Bundle state){super.onCreate(state);RecordUi.review(this);if(Build.VERSION.SDK_INT>=33)getOnBackInvokedDispatcher().registerOnBackInvokedCallback(android.window.OnBackInvokedDispatcher.PRIORITY_DEFAULT,this::finish);try{draft=SleepPlans.load(this);reminderFailure=SleepPlans.repository(this).reminderError();if(state!=null){draft.goal=state.getInt("goal");draft.bedtime=state.getInt("bedtime");draft.wake=state.getInt("wake");draft.windDown=state.getInt("wind");draft.reminderAdvance=state.getInt("advance");draft.reminder=state.getBoolean("reminder");draft.revision=state.getLong("revision");saveToken=state.getString("saveToken");reminderOnly=state.getBoolean("reminderOnly");saveFailure=state.getString("saveFailure","");restoredPicker=state.getBundle("picker");}render();}catch(Exception e){unavailable(e);} }
    @Override protected void onResume(){super.onResume();resumed=true;if(draft!=null){loadRecords();observeSave();}}
    @Override protected void onPause(){resumed=false;handler.removeCallbacks(poll);super.onPause();}
    private void loadRecords(){Records.Factory factory=Records.factory;reader.execute(()->{try(Store store=factory.open(getApplicationContext())){List<RecordEntry> rows=Records.all(store);LocalDate today=LocalDate.now();int cutoff=Math.max(0,Math.min(1439,Prefs.number(this,"statsCutoff",0)));SortedMap<LocalDate,RecordTrends.Day> week=RecordTrends.days(rows,new RecordTrends.Range(today.minusDays(6),today),cutoff);runOnUiThread(()->{if(isDestroyed())return;records=rows;days=week;failure="";historyLoaded=true;render();});}catch(Exception e){runOnUiThread(()->{if(!isDestroyed()){failure="History could not be read. "+e.getMessage();render();}});}});}
    private void unavailable(Exception e){LinearLayout body=Design.page(this,false,null,n->{});RecordUi.header(body,"Sleep goals",this::finish);Design.text(body,"Your saved plan could not be read. "+e.getMessage(),15,400,Design.MUTED);Design.button(body,"Try again",true,()->recreate());}
    static String clock(Context c,int minute){return Design.clock(c,minute);}
    static String duration(int minute){return minute>=60?minute/60+" h"+(minute%60==0?"":" "+minute%60+" min"):minute+" min";}
    static LinearLayout detail(LinearLayout body,String icon,String title,String subtitle,String value,Runnable action){Context c=body.getContext();LinearLayout row=Design.row(c);row.setMinimumHeight(Design.dp(c,64));Design.Icon glyph=new Design.Icon(c,icon,Design.BROWN);LinearLayout.LayoutParams gp=new LinearLayout.LayoutParams(Design.dp(c,26),Design.dp(c,26));gp.rightMargin=Design.dp(c,16);row.addView(glyph,gp);LinearLayout text=Design.col(c);Design.text(text,title,15,600,Design.INK);if(subtitle!=null){Design.space(text,4);Design.text(text,subtitle,11,400,Design.MUTED);}row.addView(text,new LinearLayout.LayoutParams(0,-2,1));if(value!=null){TextView current=Design.text(c,value,13,600,Design.BROWN);current.setMaxWidth(Design.dp(c,110));current.setGravity(Gravity.END);row.addView(current);}if(action!=null){row.addView(new Design.Icon(c,"chevron",Design.INK),new LinearLayout.LayoutParams(Design.dp(c,18),Design.dp(c,18)));row.setBackground(Design.touch(c,android.graphics.Color.TRANSPARENT,10));row.setOnClickListener(v->action.run());}row.setContentDescription(title);body.addView(row);return row;}
    private void render(){if(draft==null)return;LinearLayout body=Design.page(this,false,null,n->{});RecordUi.label(this,body);RecordUi.header(body,"Sleep goals",this::finish);Design.space(body,8);Design.text(body,"Sleep goal",20,600,Design.INK);Design.space(body,5);Design.text(body,"Set how much sleep you want each night.",13,400,Design.MUTED);Design.space(body,12);
        LinearLayout amount=Design.row(this);amount.setGravity(Gravity.CENTER);Button minus=counter("minus","Decrease sleep goal",()->change(-15));amount.addView(minus,new LinearLayout.LayoutParams(Design.dp(this,64),Design.dp(this,64)));TextView value=Design.text(this,"",draft.goal%60==0?76:48,700,Design.INK);value.setText(RecordUi.units(duration(draft.goal)));value.setGravity(Gravity.CENTER);value.setContentDescription("Sleep duration goal "+duration(draft.goal));value.setOnClickListener(v->chooseDuration());amount.addView(value,new LinearLayout.LayoutParams(0,Design.dp(this,88),1));amount.addView(counter("plus","Increase sleep goal",()->change(15)),new LinearLayout.LayoutParams(Design.dp(this,64),Design.dp(this,64)));body.addView(amount);Design.space(body,10);
        LinearLayout pair=Design.row(this);Design.pad(pair,12,10);pair.setBackground(Design.shape(this,Design.SOFT,16));timePair(pair,"bed","Bedtime",draft.bedtime,()->pickTime(false));View line=new View(this);line.setBackgroundColor(Design.LINE);pair.addView(line,new LinearLayout.LayoutParams(Design.dp(this,1),Design.dp(this,40)));timePair(pair,"sun","Wake-up",draft.wake,()->pickTime(true));body.addView(pair);Design.space(body,14);
        Design.text(body,"Your bedtime (last 7 nights)",14,600,Design.INK);if(!historyLoaded&&failure.isEmpty()){Design.space(body,14);Design.text(body,"Loading recorded bedtimes…",13,400,Design.MUTED);Design.space(body,30);}else if(failure.isEmpty())body.addView(new GoalChart(this,days,LocalDate.now(),draft.bedtime),new LinearLayout.LayoutParams(-1,Design.dp(this,140)));else{Design.space(body,10);Design.text(body,failure,12,400,Design.MUTED);RecordUi.quietButton(body,"Retry history",this::loadRecords);}
        String bank="Start a goal",subtitle="Build a free 14- or 30-day habit";try{List<GoalCommitment> goals=SleepPlans.goals(this);for(int i=goals.size()-1;i>=0;i--){GoalCommitment g=goals.get(i);if(g.active(LocalDate.now(ZoneId.of(g.zone)))){GoalProgress p=GoalProgress.calculate(g,records,Instant.now());bank=p.observed==0?"No days yet":GoalProgress.signed(p.balance);subtitle=g.metric.equals("duration")?"Duration · closed recorded days":"Bedtime · closed recorded days";break;}}}catch(Exception e){bank="Needs attention";subtitle="Existing goal history was kept";}
        detail(body,"report","Goal bank",subtitle,bank,()->startActivity(RecordUi.intent(this,GoalBankActivity.class)));Design.line(body);detail(body,"bell","Reminder","Get a reminder before bed",draft.reminder?draft.reminderAdvance+" min before":"Off",this::reminder);Design.line(body);detail(body,"moon","Wind-down","Put your phone down before bed",draft.windDown+" min before",this::windDown);
        Design.space(body,8);int planned=Math.floorMod(draft.wake-draft.bedtime,1440);Design.text(body,planned==draft.goal?"Planned times are separate from wake-up alarms.":"Saved times allow "+duration(planned)+". Adjust a time or goal to link this plan.",11,400,Design.MUTED);if(!saveFailure.isEmpty()){Design.space(body,6);Design.text(body,saveFailure,12,500,Design.BROWN);RecordUi.quietButton(body,"Reload saved plan",()->{draft=SleepPlans.load(this);saveFailure="";render();});}if(!reminderFailure.isEmpty()){Design.space(body,6);Design.text(body,"Plan saved. Reminder needs attention: "+reminderFailure,12,500,Design.BROWN);RecordUi.quietButton(body,"Retry saved reminder",this::retryReminder);}if(draft.reminder&&!Scheduler.allowed(this)){Design.space(body,6);Design.text(body,"Reminder needs Alarms & reminders access.",12,500,Design.BROWN);RecordUi.quietButton(body,"Open reminder access",()->startActivity(new Intent(android.provider.Settings.ACTION_REQUEST_SCHEDULE_EXACT_ALARM,android.net.Uri.parse("package:"+getPackageName()))));}
        if(draft.reminder&&!androidx.core.app.NotificationManagerCompat.from(this).areNotificationsEnabled()){Design.space(body,6);Design.text(body,"Allow notifications to see bedtime reminders.",12,500,Design.BROWN);RecordUi.quietButton(body,"Enable reminder notifications",this::notifications);}
        LinearLayout footer=RecordUi.footer(body);save=Design.button(footer,saveToken==null?"Save sleep plan":"Saving…",true,this::save);save.setEnabled(saveToken==null);if(saveToken!=null)RecordUi.enabled(body,false);if(resumed&&saveToken!=null)observeSave();restorePicker();
    }
    private void notifications(){if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS)!=android.content.pm.PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{android.Manifest.permission.POST_NOTIFICATIONS},41);else startActivity(new Intent(android.provider.Settings.ACTION_APP_NOTIFICATION_SETTINGS).putExtra(android.provider.Settings.EXTRA_APP_PACKAGE,getPackageName()));}
    @Override public void onRequestPermissionsResult(int code,String[] permissions,int[] grants){super.onRequestPermissionsResult(code,permissions,grants);if(code==41)render();}
    private Button counter(String icon,String label,Runnable action){Button b=new Button(this);b.setStateListAnimator(null);b.setElevation(0);b.setAllCaps(false);b.setPadding(0,0,0,0);b.setText(icon.equals("minus")?"−":"+");b.setTextSize(38);b.setTextColor(Design.BROWN);b.setTypeface(Design.font(this,400));b.setBackground(Design.touch(this,0xfff3e1cd,14));b.setContentDescription(label);b.setOnClickListener(v->{if(saveToken==null)action.run();});return b;}
    private void change(int amount){draft.duration(Math.max(20,Math.min(810,draft.goal+amount)));render();}
    private void chooseDuration(){if(saveToken==null)openPicker(()->SleepPicker.duration(this,"Sleep duration",draft.goal,20,810,value->{draft.duration(value);render();}));}
    private void timePair(LinearLayout parent,String icon,String title,int time,Runnable action){LinearLayout row=Design.row(this);Design.pad(row,5,2);row.addView(new Design.Icon(this,icon,Design.BROWN),new LinearLayout.LayoutParams(Design.dp(this,24),Design.dp(this,24)));LinearLayout labels=Design.col(this);labels.setPadding(Design.dp(this,10),0,0,0);Design.text(labels,title,11,400,Design.MUTED);Design.space(labels,4);Design.text(labels,clock(this,time),17,600,Design.INK);row.addView(labels,new LinearLayout.LayoutParams(0,-2,1));row.setMinimumHeight(Design.dp(this,48));row.setContentDescription("Change planned "+title.toLowerCase(Locale.ROOT));row.setOnClickListener(v->{if(saveToken==null)action.run();});parent.addView(row,new LinearLayout.LayoutParams(0,-2,1));}
    private void pickTime(boolean wake){if(saveToken!=null)return;int value=wake?draft.wake:draft.bedtime;openPicker(()->SleepPicker.time(this,wake?"Planned wake-up":"Planned bedtime",value,minutes->{if(wake)draft.wake(minutes);else draft.bedtime(minutes);render();}));}
    private void reminder(){if(saveToken!=null)return;String[] labels={"Off","At bedtime","5 min before","15 min before","30 min before","60 min before","120 min before"};int[] offsets={-1,0,5,15,30,60,120};int selected=0;for(int n=1;n<offsets.length;n++)if(draft.reminder&&offsets[n]==draft.reminderAdvance)selected=n;int current=selected;openPicker(()->SleepPicker.choices(this,"Bedtime reminder",labels,current,n->{draft.reminder=n!=0;if(n!=0)draft.reminderAdvance=offsets[n];render();}));}
    private void windDown(){if(saveToken!=null)return;int[] offsets={0,5,15,30,60,90,120};String[] labels={"At bedtime","5 min before","15 min before","30 min before","60 min before","90 min before","120 min before"};int selected=0;for(int n=0;n<offsets.length;n++)if(offsets[n]==draft.windDown)selected=n;int current=selected;openPicker(()->SleepPicker.choices(this,"Wind-down starts",labels,current,n->{draft.windDown=offsets[n];render();}));}
    private void openPicker(java.util.function.Supplier<Dialog> create){if(isFinishing()||pickerDialog!=null&&pickerDialog.isShowing())return;pickerDialog=create.get();Dialog owned=pickerDialog;owned.setOnDismissListener(d->{if(pickerDialog==owned)pickerDialog=null;});}
    private void restorePicker(){if(restoredPicker==null)return;Bundle saved=restoredPicker;restoredPicker=null;String kind=saved.getString("sleepPickerKind"),title=saved.getString("sleepPickerTitle");if("duration".equals(kind))chooseDuration();else if("time".equals(kind))pickTime("Planned wake-up".equals(title));else if("Bedtime reminder".equals(title))reminder();else if("Wind-down starts".equals(title))windDown();if(pickerDialog instanceof SleepPicker.StateDialog)pickerDialog.onRestoreInstanceState(saved);}
    private void save(){if(saveToken!=null)return;try{draft.validate();reminderOnly=false;saveToken=UUID.randomUUID().toString();render();}catch(Exception e){Ui.toast(this,e.getMessage());}}
    private void retryReminder(){if(saveToken!=null)return;reminderOnly=true;saveToken=UUID.randomUUID().toString();render();}
    private void observeSave(){if(!resumed||saveToken==null)return;SleepPlan copy=draft.copy();SleepPlans.Repository repository=SleepPlans.repository(this);SleepPlans.Reminder reminder=SleepPlans.reminders;boolean retry=reminderOnly;PlanOperations.Operation operation=PlanOperations.start(this,saveToken,app->{if(!retry)repository.save(copy);try{reminder.apply(app);repository.reminderError("");return null;}catch(Exception e){String message=e.getMessage()==null?"Scheduling unavailable.":e.getMessage();repository.reminderError(message);return message;}});if(!operation.done){handler.removeCallbacks(poll);handler.postDelayed(poll,100);return;}PlanOperations.forget(saveToken);saveToken=null;if(operation.error!=null){saveFailure="Could not finish saving: "+operation.error;render();return;}if(operation.notice!=null){reminderFailure=operation.notice;draft=repository.load();render();return;}reminderFailure="";if(retry){reminderOnly=false;Ui.toast(this,"Saved reminder scheduled.");render();return;}if(isTaskRoot())startActivity(RecordUi.intent(this,MainActivity.class));finish();}
    private final Runnable poll=this::observeSave;
    @Override public void onSaveInstanceState(Bundle state){super.onSaveInstanceState(state);if(draft==null)return;state.putInt("goal",draft.goal);state.putInt("bedtime",draft.bedtime);state.putInt("wake",draft.wake);state.putInt("wind",draft.windDown);state.putInt("advance",draft.reminderAdvance);state.putBoolean("reminder",draft.reminder);state.putLong("revision",draft.revision);state.putString("saveToken",saveToken);state.putBoolean("reminderOnly",reminderOnly);state.putString("saveFailure",saveFailure);if(pickerDialog instanceof SleepPicker.StateDialog)state.putBundle("picker",pickerDialog.onSaveInstanceState());}
    @Override public void finish(){if(saveToken!=null){Ui.toast(this,"Please wait for this save to finish.");return;}super.finish();}
    // Android 11/12 fallback; newer releases use the registered platform callback.
    @android.annotation.SuppressLint("GestureBackNavigation")
    @Override public void onBackPressed(){finish();}
    @Override public void onWindowFocusChanged(boolean focus){super.onWindowFocusChanged(focus);if(focus)RecordUi.lightBars(this);}
    void awaitReaders(long timeoutMs) throws Exception {if(reader.isShutdown()){if(!reader.awaitTermination(timeoutMs,TimeUnit.MILLISECONDS))throw new java.util.concurrent.TimeoutException("Plan readers still active");}else reader.submit(()->{}).get(timeoutMs,TimeUnit.MILLISECONDS);}
    @Override protected void onDestroy(){if(pickerDialog!=null)pickerDialog.dismiss();handler.removeCallbacks(poll);reader.shutdown();super.onDestroy();}
}
